Case 1: ! as a type — cannot-fail results, irrefutable Ok
cargo +beta new never-demo && cd never-demo
// src/main.rs — the never type `!` as a first-class type (Rust 1.100)
use std::convert::Infallible;
use std::process;

// Case 1: a diverging function. `-&gt; !` has been legal here since Rust 1.0.
fn die(msg: &str) -&gt; ! {
    eprintln!("fatal: {msg}");
    process::exit(2)
}

// Case 2: `!` written anywhere a type goes — new in 1.100.
type Never = !;

fn parse_port(s: &str) -&gt; Result&lt;u16, Never&gt; {
    // This parser cannot fail: anything unparsable maps to the default port.
    Ok(s.parse().unwrap_or(8080))
}

// Case 3: a trait whose implementors pick an error type; `!` means "cannot fail".
trait Source {
    type Error: std::fmt::Debug;
    fn read(&mut self) -&gt; Result&lt;u32, Self::Error&gt;;
}

struct Counter(u32);
impl Source for Counter {
    type Error = !; // reading a counter never fails
    fn read(&mut self) -&gt; Result&lt;u32, !&gt; {
        self.0 += 1;
        Ok(self.0)
    }
}

fn main() {
    // `!` coerces to any type, so a diverging arm fits a u32 match.
    let args: Vec&lt;String&gt; = std::env::args().collect();
    let n: u32 = match args.get(1) {
        Some(s) =&gt; s.parse().unwrap_or_else(|_| die("not a number")),
        None =&gt; 3,
    };

    // Irrefutable: the Err arm of Result&lt;_, !&gt; is uninhabited, so no match needed.
    let Ok(port) = parse_port("9000");
    println!("port = {port}");

    let mut c = Counter(0);
    let mut total = 0;
    for _ in 0..n {
        let Ok(v) = c.read();
        total += v;
    }
    println!("sum of first {n} reads = {total}");

    // Infallible is now the same type as `!`.
    let same: fn(Infallible) -&gt; ! = |x| x;
    let _ = same;
    let Ok(wide) = u64::try_from(7u8); // TryFrom via Into: Error = Infallible = !
    println!("wide = {wide}");
    println!("size_of::&lt;Result&lt;u32, !&gt;&gt;() = {}", std::mem::size_of::&lt;Result&lt;u32, !&gt;&gt;());
    println!("size_of::&lt;Result&lt;u32, String&gt;&gt;() = {}", std::mem::size_of::&lt;Result&lt;u32, String&gt;&gt;());
}
