// fused_demo.rs
use std::iter::{Fuse, FusedIterator};

struct OnceThenWeird {
    state: u8,
}
impl Iterator for OnceThenWeird {
    type Item = i32;
    fn next(&mut self) -&gt; Option&lt;i32&gt; {
        self.state += 1;
        match self.state {
            1 =&gt; Some(10),
            2 =&gt; None,
            3 =&gt; Some(99), // zombie value — bad manners
            _ =&gt; None,
        }
    }
}

fn main() {
    let mut raw = OnceThenWeird { state: 0 };
    println!("raw: {:?} {:?} {:?} {:?}", raw.next(), raw.next(), raw.next(), raw.next());

    let mut fused: Fuse&lt;_&gt; = (OnceThenWeird { state: 0 }).fuse();
    println!(
        "fused: {:?} {:?} {:?} {:?}",
        fused.next(),
        fused.next(),
        fused.next(),
        fused.next()
    );
    fn assert_fused&lt;I: FusedIterator&gt;(_: &I) {}
    assert_fused(&fused);
}
